# Implementasi Simulator Model Tabel Tak Terbatas (Unbounded Table) Spark Structured Streaming
class UnboundedTableSimulator:
    def __init__(self):
        self.unbounded_input_table = []  # Aliran data masuk append-only
        self.result_table = {}           # Tabel hasil analitis terkini (Result Table)

    def trigger_batch(self, new_records):
        # Tambahkan data baru ke Unbounded Table
        self.unbounded_input_table.extend(new_records)

        # Eksekusi kueri agregasi inkremental: SELECT device, COUNT(*), SUM(temp)
        for r in new_records:
            dev = r['device']
            if dev not in self.result_table:
                self.result_table[dev] = {'count': 0, 'sum_temp': 0.0}
            self.result_table[dev]['count'] += 1
            self.result_table[dev]['sum_temp'] += r['temp']

        return self.result_table

stream_table = UnboundedTableSimulator()

# Trigger 1: Masuk 3 record awal
res1 = stream_table.trigger_batch([
    {'device': 'sensor_A', 'temp': 24.5},
    {'device': 'sensor_B', 'temp': 31.0},
    {'device': 'sensor_A', 'temp': 25.5}
])

# Trigger 2: Masuk 2 record tambahan
res2 = stream_table.trigger_batch([
    {'device': 'sensor_A', 'temp': 26.0},
    {'device': 'sensor_B', 'temp': 30.5}
])

print('Hasil Evaluasi Model Unbounded Table (Incremental Stream Execution):')
print(f'  Total Baris di Input Unbounded Table: {len(stream_table.unbounded_input_table)} baris')
print('  Status Terkini Result Table (Pasca Trigger #2):')
for dev, stats in res2.items():
    avg = stats['sum_temp'] / stats['count']
    print(f'    - [{dev}]: Cekatan={stats["count"]} event | Rata-rata Suhu={avg:.2f}°C')
print('Kesimpulan: Structured Streaming mengabstraksikan stream sebagai tabel relasional dinamis.')

# Demonstrasi Distorsi Analitis: Event Time vs Processing Time pada Data Tertunda Jaringan
class TimeDomainAnalyzer:
    @staticmethod
    def aggregate_by_processing_time(events):
        # Pengelompokan berdasarkan waktu worker memproses (misal: semua masuk bucket Menit 12)
        buckets = {}
        for e in events:
            p_minute = e['processing_time_min']
            buckets[p_minute] = buckets.get(p_minute, 0) + e['amount']
        return buckets

    @staticmethod
    def aggregate_by_event_time(events):
        # Pengelompokan objektif berdasarkan stempel waktu kejadian asli (Event Time)
        buckets = {}
        for e in events:
            e_minute = e['event_time_min']
            buckets[e_minute] = buckets.get(e_minute, 0) + e['amount']
        return buckets

# Skenario: 3 transaksi terjadi di Menit 10, namun tertahan buffering jaringan dan baru diproses di Menit 12
stream_events = [
    {'tx_id': 1, 'amount': 100, 'event_time_min': 10, 'processing_time_min': 12},
    {'tx_id': 2, 'amount': 200, 'event_time_min': 10, 'processing_time_min': 12},
    {'tx_id': 3, 'amount': 150, 'event_time_min': 11, 'processing_time_min': 12}
]

proc_agg = TimeDomainAnalyzer.aggregate_by_processing_time(stream_events)
event_agg = TimeDomainAnalyzer.aggregate_by_event_time(stream_events)

print('Evaluasi Dampak Domain Waktu pada Agregasi Finansial:')
print(f'  1. Agregasi Processing Time : {proc_agg} (Seluruh $450 menumpuk di Menit 12 - BIAS!)')
print(f'  2. Agregasi Event Time      : {event_agg} (Menit 10=$300, Menit 11=$150 - AKURAT!)')
print('Kesimpulan: Event Time menjaga kebenaran temporal data terlepas dari latensi jaringan.')

# Implementasi Simulator Stateful Stream Processing dengan LSM-Style State Store
class RocksDBStateStoreSimulator:
    def __init__(self):
        # Simulasi LSM-Tree MemTable (RAM) dan SSTables (Disk)
        self.memtable = {}
        self.sstables_disk = {}

    def put_state(self, key, value):
        self.memtable[key] = value
        if len(self.memtable) >= 3:
            # Flush MemTable ke SSTable disk lokal
            self._flush_to_disk()

    def _flush_to_disk(self):
        self.sstables_disk.update(self.memtable)
        self.memtable = {}

    def get_state(self, key):
        # Cari di MemTable dulu, jika tidak ada cari di disk SSTable
        if key in self.memtable:
            return self.memtable[key]
        return self.sstables_disk.get(key, None)

class StatefulUserSessionTracker:
    def __init__(self):
        self.state_store = RocksDBStateStoreSimulator()

    def process_user_action(self, user_id, action_val):
        # Ambil state lama pengguna dari State Store
        prev_state = self.state_store.get_state(user_id) or {'total_actions': 0, 'total_spent': 0.0}
        # Mutasi state inkremental
        new_state = {
            'total_actions': prev_state['total_actions'] + 1,
            'total_spent': prev_state['total_spent'] + action_val
        }
        # Simpan kembali ke state store
        self.state_store.put_state(user_id, new_state)
        return new_state

tracker = StatefulUserSessionTracker()
tracker.process_user_action('user_1', 50.0)
tracker.process_user_action('user_2', 120.0)
tracker.process_user_action('user_1', 75.0)  # Pembaruan state user_1
u1_final = tracker.process_user_action('user_1', 25.0)

print('Hasil Evaluasi Stateful Stream Processing (RocksDB State Store):')
print(f'  Status Akhir User 1: Total Aksi={u1_final["total_actions"]} | Akumulasi Belanja=${u1_final["total_spent"]:.2f}')
print(f'  Kondisi MemTable RAM : {tracker.state_store.memtable}')
print(f'  Kondisi SSTable Disk : {tracker.state_store.sstables_disk}')
print('Kesimpulan: State store mempertahankan konteks historis pengguna secara persisten dan efisien.')

