# Simulator Evaluasi Tiga Output Mode Structured Streaming (Append, Complete, Update)
class StreamingOutputModeSimulator:
    @staticmethod
    def evaluate_output_modes(prev_state, current_state):
        # Complete Mode: Kirim SELURUH tabel terkini
        complete_payload = current_state.copy()

        # Update Mode: Hanya kirim baris yang nilainya berubah atau baru muncul
        update_payload = {}
        for k, v in current_state.items():
            if k not in prev_state or prev_state[k] != v:
                update_payload[k] = v

        # Append Mode: Hanya kirim baris baru yang sebelumnya belum ada (untuk stateless)
        append_payload = {}
        for k, v in current_state.items():
            if k not in prev_state:
                append_payload[k] = v

        return {
            'complete_count': len(complete_payload),
            'update_count': len(update_payload),
            'append_count': len(append_payload),
            'update_items': update_payload
        }

# State Trigger 1: Kategori A=$100, B=$200
state_t1 = {'A': 100, 'B': 200}
# State Trigger 2: Kategori B diperbarui jadi $250, C baru muncul $50 (A tidak berubah)
state_t2 = {'A': 100, 'B': 250, 'C': 50}

modes_res = StreamingOutputModeSimulator.evaluate_output_modes(state_t1, state_t2)

print('Evaluasi Output Mode Structured Streaming pada Trigger #2:')
print(f'  1. Complete Mode: Menulis seluruh {modes_res["complete_count"]} record (A, B, C ditulis ulang)')
print(f'  2. Update Mode  : Menulis {modes_res["update_count"]} record termutasi: {modes_res["update_items"]}')
print(f'  3. Append Mode  : Menulis {modes_res["append_count"]} record entri baru murni')
print('Kesimpulan: Update mode sangat efisien untuk sink basis data key-value.')

# Implementasi Simulator Two-Phase Commit (2PC) Transactional Sink untuk End-to-End EOS
class TwoPhaseCommitSinkSimulator:
    def __init__(self):
        self.staging_area = {}      # Data prepared (belum visible)
        self.committed_storage = []  # Data final visible publik
        self.checkpoint_wal = []    # Log transaksi engine

    def prepare_transaction(self, tx_id, records):
        # Fase 1: Tulis data ke staging sementara
        self.staging_area[tx_id] = records
        return {'phase': 'PREPARED', 'tx_id': tx_id, 'records': len(records)}

    def commit_transaction(self, tx_id):
        # Fase 2: Checkpoint engine sukses -> Commit final all-or-nothing
        if tx_id not in self.staging_area:
            return {'status': 'FAILED_TX_NOT_FOUND'}

        # Catat ke WAL lalu pindahkan data ke penyimpanan publik
        self.checkpoint_wal.append({'tx_id': tx_id, 'status': 'COMMITTED'})
        self.committed_storage.extend(self.staging_area[tx_id])
        del self.staging_area[tx_id]
        return {'status': 'SUCCESS_COMMITTED', 'total_visible': len(self.committed_storage)}

    def rollback_transaction(self, tx_id):
        if tx_id in self.staging_area:
            del self.staging_area[tx_id]
        return {'status': 'ROLLED_BACK'}

sink = TwoPhaseCommitSinkSimulator()
# Batch 1 Berhasil: Prepare -> Commit
sink.prepare_transaction('TX-101', [{'id': 1, 'val': 100}, {'id': 2, 'val': 200}])
c1 = sink.commit_transaction('TX-101')

# Batch 2 Mengalami Kegagalan: Prepare -> Crash -> Rollback!
sink.prepare_transaction('TX-102', [{'id': 3, 'val': 300}])
r2 = sink.rollback_transaction('TX-102')

print('Hasil Evaluasi Two-Phase Commit Transactional Sink:')
print(f'  Status Commit TX-101   : {c1["status"]} (Data menjadi visible: {c1["total_visible"]} record)')
print(f'  Status Rollback TX-102 : {r2["status"]} (Data di staging dibuang bersih)')
print(f'  Penyimpanan Publik Akhir: {sink.committed_storage}')
print('Kesimpulan: 2PC Sink mengeliminasi partial writes saat terjadi kegagalan sistem.')

# Implementasi Simulator Asynchronous Barrier Snapshotting Apache Flink (Chandy-Lamport variant)
class FlinkBarrierAlignmentSimulator:
    def __init__(self, num_input_channels=2):
        self.num_channels = num_input_channels
        self.received_barriers = {}
        self.operator_state = {'counter': 0}
        self.persisted_snapshots = []

    def receive_input(self, channel_id, item):
        # Jika item adalah Barrier Checkpoint
        if isinstance(item, str) and item.startswith('BARRIER_'):
            barrier_id = item
            if barrier_id not in self.received_barriers:
                self.received_barriers[barrier_id] = set()
            self.received_barriers[barrier_id].add(channel_id)

            # Periksa apakah seluruh channel telah menyelaraskan barrier (Alignment Complete)
            if len(self.received_barriers[barrier_id]) == self.num_channels:
                # Ambil snapshot state operator secara atomik!
                snapshot_data = self.operator_state.copy()
                self.persisted_snapshots.append({'barrier': barrier_id, 'state': snapshot_data})
                del self.received_barriers[barrier_id]
                return {'action': 'SNAPSHOT_TAKEN', 'barrier': barrier_id, 'state': snapshot_data}
            else:
                return {'action': 'WAITING_FOR_ALIGNMENT', 'received_from': list(self.received_barriers[barrier_id])}

        # Jika item adalah data stream normal: proses dan mutasi state
        self.operator_state['counter'] += item
        return {'action': 'PROCESSED', 'state': self.operator_state['counter']}

operator = FlinkBarrierAlignmentSimulator(num_input_channels=2)
# Channel 0 memproses data dan mengirim Barrier #1
operator.receive_input(channel_id=0, item=10)
a1 = operator.receive_input(channel_id=0, item='BARRIER_1')

# Channel 1 memproses data lalu mengirim Barrier #1 (Alignment Selesai!)
operator.receive_input(channel_id=1, item=25)
a2 = operator.receive_input(channel_id=1, item='BARRIER_1')

print('Demonstrasi Asynchronous Barrier Snapshotting Apache Flink:')
print(f'  Channel 0 Kirim Barrier 1: {a1["action"]} (Menunggu channel 1)')
print(f'  Channel 1 Kirim Barrier 1: {a2["action"]} -> State Terkunci={a2.get("state")}')
print(f'  Snapshot Tersimpan di Storage Persisten: {operator.persisted_snapshots}')
print('Kesimpulan: Barrier mengalir bersama data untuk snapshotting global tanpa downtime.')
